# MECHANISM: Use a piecewise linear function to prioritize bins based on their remaining capacity with more granular thresholds.

def priority(item, bins):
    thresholds = np.array([50, 100, 125, 140])
    scores = np.array([0.25, 0.5, 0.75, 1.0])
    return np.interp(bins - item, thresholds, scores, left=0.0, right=1.0)

